def get_total_number_of_sequences(m, n):
    # Initialize a DP table where dp[k][i] represents the number of sequences of length k ending with value i
    dp_prev = [0] * (m + 1)

    # Base case: sequences of length 1 ending with any value i (1 <= i <= m)
    for i in range(1, m + 1):
        dp_prev[i] = 1

    for k in range(2, n + 1):
        dp_current = [0] * (m + 1)
        for i in range(1, m + 1):
            for j in range(2 * i, m + 1):
                dp_current[j] += dp_prev[i]
        dp_prev = dp_current

    # Sum up all possible sequences of length n
    return sum(dp_prev)
```

