def find_kth(arr1, arr2, k):
    # Initialize pointers for both arrays
    m, n = len(arr1), len(arr2)

    # Ensure k is valid
    if k <= 0 or k > m + n:
        return None

    i = j = 0
    for _ in range(k):
        if i < m and j < n:
            if arr1[i] < arr2[j]:
                current = arr1[i]
                i += 1
            else:
                current = arr2[j]
                j += 1
        elif i < m:
            current = arr1[i]
            i += 1
        else:
            current = arr2[j]
            j += 1

