def max_sum(arr):
    from functools import lru_cache

    def max_increasing_subseq_sum(start, end):
        @lru_cache(maxsize=None)
        def helper(i):
            max_sum = arr[i]
            for j in range(i-1, start-1, -1):
                if arr[j] < arr[i]:
                    max_sum = max(max_sum, arr[i] + helper(j))
            return max_sum
        return max(helper(i) for i in range(start, end+1))

    def max_decreasing_subseq_sum(start, end):
        @lru_cache(maxsize=None)
        def helper(i):
            max_sum = arr[i]
            for j in range(i+1, end+1):
                if arr[i] > arr[j]:
                    max_sum = max(max_sum, arr[i] + helper(j))
            return max_sum
        return max(helper(i) for i in range(start, end+1))

    max_total = 0
    n = len(arr)

    if n == 0:
        return 0

    for i in range(n):
        left_sum = max_increasing_subseq_sum(0, i)
        right_sum = max_decreasing_subseq_sum(i, n-1)
        total_sum = left_sum + right_sum - arr[i]
        max_total = max(max_total, total_sum)

    return max_total
