def eulerian_num(n, m):
    # Initialize DP table for A(k, i) where k ranges from 0 to n, and i ranges from 0 to k-1
    dp = [[0] * n for _ in range(n)]

    # Base cases initialization
    for k in range(n):
        for i in range(k):
            if i == 0 or i == k - 1:
                dp[k][i] = 1
            else:
                # Initial values to be built iteratively
                dp[k][i] = 0

    # Triangle initialization
    dp[0][0] = 1

    # Fill the triangle iteratively
    for k in range(1, n):
        for i in range(k):
            if i == 0:
                dp[k][i] = (k + 1) * dp[k - 1][i]
            else:
                dp[k][i] = (k - i + 1) * dp[k - 1][i - 1] + i * dp[k - 1][i]

    return dp[n - 1][m - 1]
