def maxAverageOfPath(cost):
    if not cost or not cost[0]:
        return 0.0

    n = len(cost)
    # Initialize DP tables for total cost and number of steps
    total = [[0]*n for _ in range(n)]
    steps = [[0]*n for _ in range(n)]

    total[0][0] = cost[0][0]
    steps[0][0] = 1

    for i in range(n):
        for j in range(n):
            if i == 0 and j == 0:
                continue
            from_top = float('-inf')
            from_left = float('-inf')

            # Coming from top
            if i > 0:
                from_top = total[i-1][j] + cost[i][j]
            # Coming from left
            if j > 0:
                from_left = total[i][j-1] + cost[i][j]

            if max(from_top, from_left) == float('-inf'):
                continue  # Shouldn't happen since bottom-right should be reachable

            max_val = max(from_top, from_left)
            total[i][j] = max_val
            if from_top == max_val:
                steps[i][j] = steps[i-1][j] + 1
            else:
                steps[i][j] = steps[i][j-1] + 1

    max_avg = total[-1][-1] / steps[-1][-1]
    return max_avg
