```python
def eulerian_num(n, m):
    if n == 0:
        return 1 if m == 0 else 0
    if m == 0 or m == n - 1:
        return 1

    # Use dynamic programming/memoization for efficiency
    dp = [[0] * n for _ in range(n)]
    for i in range(n):
        dp[i][0] = 1 if i == 0 else 0
        dp[i][i] = 1

    for i in range(1, n):
        for j in range(1, i):
            dp[i][j] = (j + 1) * dp[i - 1][j] + (i - j) * dp[i - 1][j - 1]

    return dp[n - 1][m]
