def find_solution(a, b, n):
    # Using Extended Euclidean Algorithm to check for solutions
    def extended_gcd(a, b):
        x_old, x, y_old, y = 0, 1, 1, 0
        while b:
            q = a // b
            x_old, x = x, x_old - q * x
            y_old, y = y, y_old - q * y
            a, b = b, a % b
        return (x_old, y_old, a)

    (x0, y0, gcd) = extended_gcd(a, b)

